import unittest
from solution import unique

class ContractTests(unittest.TestCase):
    def test_00(self):
        self.assertEqual(unique([3,1,3,2,1]), [3,1,2])
    def test_01(self):
        self.assertEqual(unique([]), [])
    def test_02(self):
        self.assertEqual(unique(['a','a','b']), ['a','b'])

if __name__ == '__main__':
    unittest.main()
